enum Level { Novice, Intermediate, Expert }
enum Format { Open, MultipleChoice }

fn format_for(level: Level, open_questions: bool) -> Format {
    match level {
        Level::Expert => Format::Open,
        _ => Format::MultipleChoice,
    }
}

// caller
let format = format_for(level, config.open_questions);

struct Settings {
    open_questions: Option<bool>,
}

impl Settings {
    /// `self` is the file layer, `over` is the CLI/env layer (higher priority).
    fn overlay(mut self, over: Settings) -> Settings {
        self.open_questions = self.open_questions.or(over.open_questions);
        self
    }
}

#[derive(Clone, Copy)]
enum Level { Novice, Expert }

fn style(level: Level, open: bool) -> &'static str {
    match level {
        Level::Expert if open => "open",
        _ => "choice",
    }
}

fn main() {
    println!("{}", style(Level::Expert, false));
}
